#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<pair<int, int>> v(k, {0, 0});

    for (int j = 0; j < n; ++j) {
        int a;
        cin >> a;
        if (a % 2 == 0)
            ++v[j % k].first;
        else
            ++v[j % k].second;
    }

    int c = 0;
    for (int i = 0; i < k; ++i)
        c += min(v[i].first, v[i].second);

    cout << c;
    return 0;
}

